'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const read=name=>fs.readFileSync(path.join(__dirname,name),'utf8');
const js=read('app.js'),css=read('style.css');
const start=js.indexOf('const playbackDeviceIcon='),end=js.indexOf('// App preferences',start);
assert.ok(start>=0&&end>start);
const {playbackDeviceIcon,dropdownChevron}=new Function(js.slice(start,end)+';return {playbackDeviceIcon,dropdownChevron};')();
assert.ok(playbackDeviceIcon.includes('class="icon device-icon"'));
assert.ok(playbackDeviceIcon.includes('<rect'));
assert.ok(playbackDeviceIcon.includes('M1.5 21h21'));
assert.ok(dropdownChevron.includes('class="dropdown-chevron"'));
assert.ok(dropdownChevron.includes('m4 6 4 4 4-4'));
const line=js.split('\n').find(line=>line.startsWith('function renderSpotify(){'));
const page={innerHTML:''};
new Function('page','modeOptions','transportIcon','playbackDeviceIcon','dropdownChevron','liveEnabled','updateSpotify',line+';renderSpotify();')(page,()=>'<option>Wi-Fi</option>',()=>'',playbackDeviceIcon,dropdownChevron,false,()=>{});
assert.ok(page.innerHTML.includes('id="deviceCaption" class="device-caption">PLAYBACK DEVICE'));
assert.ok(page.innerHTML.includes(playbackDeviceIcon+'<span id="deviceLabel">'));
assert.ok(page.innerHTML.includes(dropdownChevron+'</button><button id="saveSong"'));
assert.ok(!page.innerHTML.includes('⌄'));
assert.ok(js.includes("put('deviceLabel',playback.device)"));
assert.ok(js.includes("text('deviceLabel',s.device||'Select device')"));
assert.ok(js.includes("s.inactive&&s.device?'LAST PLAYBACK DEVICE':'PLAYBACK DEVICE'"));
assert.ok(js.includes('chevron.innerHTML=dropdownChevron'));
assert.ok(!js.includes("chevron.textContent='⌄'"));
assert.ok(css.includes('.spotify-header .themed-select{width:fit-content;min-width:0;max-width:70%'));
assert.ok(css.includes('.spotify-header select{letter-spacing:0;min-width:0;width:fit-content'));
assert.ok(css.includes('#deviceSelect .device-icon{color:var(--spotify-accent)'));
assert.ok(css.includes('.player-bottom .device-copy{display:flex;flex:1;min-width:0;flex-direction:column'));
assert.ok(css.includes('text-overflow:ellipsis;font-size:14px;line-height:1.2'));
assert.ok(css.includes('.dropdown-chevron{display:block;width:16px;height:16px'));
console.log('Spotify device control and dropdown checks passed');
